    async def edit_quota(
        self, project_id: str, body: models.PublicCloudQuotaQuotaUpdate
    ) -> models.PublicCloudQuotaQuota:
        """edit_quota calls PUT /v2/publicCloud/project/{projectId}/quota: Update the project quota

        Updates the project quota region by region. Each region listed in `targetSpec.regions` is
        added or updated, and the regions you omit are left unchanged, so raising the quota of one
        region does not require restating the others. Unlike the other update routes of this API,
        this list is merged, not replaced. `preventAutomaticQuotaUpgrade` is required.

        Args:
            project_id: Project ID
            body: the request body

        Requires the IAM action publicCloudProject:apiovh:quota/edit.
        """
        return await self._call(
            _r.OP_EDIT_QUOTA,
            path_params={
                "projectId": project_id,
            },
            body=body,
            body_type=models.PublicCloudQuotaQuotaUpdate,
            result=models.PublicCloudQuotaQuota,
        )

